 6	
 7	/// Another specialization trait for Vec::from_iter
 8	/// necessary to manually prioritize overlapping specializations
 9	/// see [`SpecFromIter`](super::SpecFromIter) for details.
10	pub(super) trait SpecFromIterNested<T, I> {
11	    fn from_iter(iter: I) -> Self;
12	}
13	
14	impl<T, I> SpecFromIterNested<T, I> for Vec<T>
15	where
16	    I: Iterator<Item = T>,
17	{
18	    default fn from_iter(mut iterator: I) -> Self {
19	        // Unroll the first iteration, as the vector is going to be
20	        // expanded on this iteration in every case when the iterable is not
21	        // empty, but the loop in extend_desugared() is not going to see the
22	        // vector being full in the few subsequent loop iterations.
23	        // So we get better branch prediction.
24	        let mut vector = match iterator.next() {
25	            None => return Vec::new(),
26	            Some(element) => {
27	                let (lower, _) = iterator.size_hint();
28	                let initial_capacity =
29	                    cmp::max(RawVec::<T>::MIN_NON_ZERO_CAP, lower.saturating_add(1));
30	                let mut vector = Vec::with_capacity(initial_capacity);
31	                unsafe {
32	                    // SAFETY: We requested capacity at least 1
33	                    ptr::write(vector.as_mut_ptr(), element);
34	                    vector.set_len(1);
35	                }
36	                vector
37	            }
38	        };
39	        // must delegate to spec_extend() since extend() itself delegates
40	        // to spec_from for empty Vecs
41	        <Vec<T> as SpecExtend<T, I>>::spec_extend(&mut vector, iterator);
42	        vector
43	    }
44	}
45	
46	impl<T, I> SpecFromIterNested<T, I> for Vec<T>
47	where
48	    I: TrustedLen<Item = T>,
49	{
50	    fn from_iter(iterator: I) -> Self {
51	        let mut vector = match iterator.size_hint() {
52	            (_, Some(upper)) => Vec::with_capacity(upper),
53	            // TrustedLen contract guarantees that `size_hint() == (_, None)` means that there
54	            // are more than `usize::MAX` elements.
55	            // Since the previous branch would eagerly panic if the capacity is too large
56	            // (via `with_capacity`) we do the same here.
57	            _ => panic!("capacity overflow"),
58	        };
59	        // reuse extend specialization for TrustedLen
60	        vector.spec_extend(iterator);
61	        vector
62	    }
63	}

 1	use core::mem::ManuallyDrop;
 2	use core::ptr;
 3	
 4	use super::{IntoIter, SpecExtend, SpecFromIterNested, Vec};
 5	
 6	/// Specialization trait used for Vec::from_iter
 7	///
 8	/// ## The delegation graph:
 9	///
10	/// ```text
11	/// +-------------+
12	/// |FromIterator |
13	/// +-+-----------+
14	///   |
15	///   v
16	/// +-+---------------------------------+  +---------------------+
17	/// |SpecFromIter                    +---->+SpecFromIterNested   |
18	/// |where I:                        |  |  |where I:             |
19	/// |  Iterator (default)------------+  |  |  Iterator (default) |
20	/// |  vec::IntoIter                 |  |  |  TrustedLen         |
21	/// |  InPlaceCollect--(fallback to)-+  |  +---------------------+
22	/// +-----------------------------------+
23	/// ```
24	pub(super) trait SpecFromIter<T, I> {
25	    fn from_iter(iter: I) -> Self;
26	}
27	
28	impl<T, I> SpecFromIter<T, I> for Vec<T>
29	where
30	    I: Iterator<Item = T>,
31	{
32	    default fn from_iter(iterator: I) -> Self {
33	        SpecFromIterNested::from_iter(iterator)
34	    }
35	}
36	
37	impl<T> SpecFromIter<T, IntoIter<T>> for Vec<T> {
38	    fn from_iter(iterator: IntoIter<T>) -> Self {
39	        // A common case is passing a vector into a function which immediately
40	        // re-collects into a vector. We can short circuit this if the IntoIter
41	        // has not been advanced at all.
42	        // When it has been advanced We can also reuse the memory and move the data to the front.
43	        // But we only do so when the resulting Vec wouldn't have more unused capacity
44	        // than creating it through the generic FromIterator implementation would. That limitation
45	        // is not strictly necessary as Vec's allocation behavior is intentionally unspecified.
46	        // But it is a conservative choice.
47	        let has_advanced = iterator.buf != iterator.ptr;
48	        if !has_advanced || iterator.len() >= iterator.cap / 2 {
49	            unsafe {
50	                let it = ManuallyDrop::new(iterator);
51	                if has_advanced {
52	                    ptr::copy(it.ptr.as_ptr(), it.buf.as_ptr(), it.len());
53	                }
54	                return Vec::from_parts(it.buf, it.len(), it.cap);
55	            }
56	        }
57	
58	        let mut vec = Vec::new();
59	        // must delegate to spec_extend() since extend() itself delegates
60	        // to spec_from for empty Vecs
61	        vec.spec_extend(iterator);
62	        vec
63	    }
64	}

