159	    fn as_uninit_slice_mut(&mut self) -> &mut [MaybeUninit<T>] {
160	        let len = N / size_of::<T>();
161	
162	        // SAFETY: `_align` ensures we are correctly aligned.
163	        unsafe { core::slice::from_raw_parts_mut(self.storage.as_mut_ptr().cast(), len) }
164	    }
