190	    where
191	        F: FnMut(B, Self::Item) -> T,
192	        T: Try<Output = B>,
193	    {
194	        self.iter
195	            .try_fold(init, |acc, x| match Try::branch(x) {
196	                ControlFlow::Continue(x) => ControlFlow::from_try(f(acc, x)),
197	                ControlFlow::Break(r) => {
198	                    *self.residual = Some(r);
199	                    ControlFlow::Break(try { acc })
200	                }
201	            })
202	            .into_try()
203	    }
